加入ではなく、部屋を買えば法律上当然にメンバーになる（脱退
不可）。年に1回以上開かれる「集会（総会）」が国会のような
最高意思決定機関で、「規約」がマンションの憲法にあたる。
何を決めるにも多数決だが、事柄の重さによって必要な賛成の
