・イ方式・ハ方式では原則として保証契約が必要★
　（ロ方式でも管理費用相当額を収納口座で預貯金として
　　管理する場合は保証契約が必要）
・分別管理は管理業者の法令上の義務であり、
　管理組合の承諾があっても省略できない★

